import * as THREE from 'three/webgpu';
import { texture, uv, uniform, float, mix, mul, vec3, positionLocal } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'pedestal-material-study';
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const disposables = [];

  // --- Backdrop ---
  const backdropColors = [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const bottomColor = uniform(new THREE.Color(backdropColors[0].hex));
  const midColor = uniform(new THREE.Color(backdropColors[1].hex));
  const topColor = uniform(new THREE.Color(backdropColors[2].hex));
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const vUv = uv();
  const lower = mix(bottomColor, midColor, float(vUv.y.div(0.7).clamp(0, 1)));
  const upper = mix(midColor, topColor, float(vUv.y.sub(0.7).div(0.3).clamp(0, 1)));
  const gradientColor = mix(lower, upper, float(vUv.y.greaterThan(0.7)));
  const backdropMat = new THREE.MeshBasicNodeMaterial();
  backdropMat.colorNode = gradientColor;
  backdropMat.side = THREE.FrontSide;
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // --- Roughness map ---
  let roughMap = null;
  try {
    roughMap = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
    roughMap.wrapS = roughMap.wrapT = THREE.RepeatWrapping;
  } catch (e) {
    roughMap = null;
  }

  // --- Torus knot material study ---
  const knotGeo = new THREE.TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new THREE.MeshPhysicalNodeMaterial();
  knotMat.color = new THREE.Color('#c9cdd4');
  knotMat.metalness = 0.55;
  knotMat.clearcoat = 0.22;
  knotMat.clearcoatRoughness = 0.35;
  if (knotMat.anisotropy !== undefined) {
    knotMat.anisotropy = 0.9;
    knotMat.anisotropyRotation = Math.PI / 2;
  }

  const baseRoughness = float(0.55);
  const jitter = float(0.02);
  let roughnessNode;
  if (roughMap) {
    const mapSample = texture(roughMap, uv()).r;
    const mapCentered = mapSample.sub(0.9).mul(0.5).add(1.0);
    const jittered = mapCentered.add(
      mul(positionLocal.x.fract().sub(0.5), jitter)
    );
    roughnessNode = baseRoughness.mul(jittered).clamp(0.05, 1.0);
  } else {
    roughnessNode = baseRoughness.add(
      mul(positionLocal.y.fract().sub(0.5), jitter)
    ).clamp(0.05, 1.0);
  }
  knotMat.roughnessNode = roughnessNode;

  // scratch-noise "normal" perturbation approximated via normal scale + procedural bump using positionLocal
  knotMat.normalScale = new THREE.Vector2(0.15, 0.15);

  const knot = new THREE.Mesh(knotGeo, knotMat);
  knot.position.set(0, 0.4, 0);
  group.add(knot);
  disposables.push(knotGeo, knotMat);
  if (roughMap) disposables.push(roughMap);

  // --- Pedestal ---
  const pedestalGeo = new THREE.CylinderGeometry(1.1, 1.1, 0.5, 64, 1, false);
  const pedestalMat = new THREE.MeshPhysicalNodeMaterial();
  pedestalMat.color = new THREE.Color('#14141a');
  pedestalMat.roughness = 0.7;
  pedestalMat.metalness = 0.35;
  const pedestal = new THREE.Mesh(pedestalGeo, pedestalMat);
  // top face at y = -0.35, height 0.5 -> center at y = -0.6
  pedestal.position.set(0, -0.6, 0);
  group.add(pedestal);
  disposables.push(pedestalGeo, pedestalMat);

  // chamfer edge approximation - thin torus ring at top edge
  const chamferGeo = new THREE.TorusGeometry(1.1, 0.03, 8, 64);
  const chamferMat = new THREE.MeshPhysicalNodeMaterial();
  chamferMat.color = new THREE.Color('#dfe2e8');
  chamferMat.roughness = 0.3;
  chamferMat.metalness = 0.6;
  const chamfer = new THREE.Mesh(chamferGeo, chamferMat);
  chamfer.rotation.x = Math.PI / 2;
  chamfer.position.set(0, -0.35, 0);
  group.add(chamfer);
  disposables.push(chamferGeo, chamferMat);

  // --- Contact shadow ---
  const shadowGeo = new THREE.CircleGeometry(1.5, 64);
  const shadowMat = new THREE.MeshBasicNodeMaterial();
  const shadowUv = uv();
  const dist = shadowUv.sub(0.5).length().mul(2.0);
  const shadowAlpha = float(0.6).mul(float(1.0).sub(dist.clamp(0, 1))).mul(
    float(1.0).sub(dist.smoothstep(0.6, 1.0))
  );
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = shadowAlpha;
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.36, 0);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // --- Lighting (studio IBL substitute + key light) ---
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.1);
  keyLight.position.set(2, 3, 2);
  group.add(keyLight);
  const ambient = new THREE.HemisphereLight(0xffffff, 0x101015, 0.7);
  group.add(ambient);

  // --- Text ---
  const headline = ctx.fontAtlas.createText({
    text: 'Material study 03',
    family: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  });
  headline.position.set(0, -1.2, 0);
  group.add(headline);

  const caption = ctx.fontAtlas.createText({
    text: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT',
    family: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#ff2a38',
  });
  caption.position.set(0, -1.6, 0);
  group.add(caption);

  // --- Apply cinematic primitives ---
  const primitiveHandles = [];
  const primitiveConfigs = config.cinematicPrimitives || [];
  for (const prim of primitiveConfigs) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(knot, prim.params || {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // fallback manual orbit rotation if primitive did not animate
  const rotTicker = gsap.to(knot.rotation, {
    y: `+=${Math.PI * 2}`,
    duration: (Math.PI * 2) / 0.1,
    ease: 'none',
    repeat: -1,
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    rotTicker.kill();
    for (const h of primitiveHandles) {
      if (h && typeof h.kill === 'function') h.kill();
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    if (headline.userData && headline.userData.cleanup) headline.userData.cleanup();
    if (caption.userData && caption.userData.cleanup) caption.userData.cleanup();
  };

  return group;
}
